('26287', '1', '2026-06-09 07:35:50', '2026-06-09 05:35:50', '<!-- wp:group {\"className\":\"iss-ausstellung-station iss-ausstellung-station\\u002d\\u002dsplit\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station iss-ausstellung-station--split\"><!-- wp:image {\"id\":26366,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://192.168.2.31:8082/wp-content/uploads/2026/06/ALB_003-3.webp\" alt=\"\" class=\"wp-image-26366\"/><figcaption class=\"wp-element-caption\">Presstellerfertigung, Werk für Fernmeldewesen, 1951</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station__copy\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station__copy\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact iss-ausstellung-station__kicker\"} -->\n<p class=\"iss-kicker iss-kicker--compact iss-ausstellung-station__kicker\">Arbeit</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Präzision war keine Nebenarbeit</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>In der Presstellerfertigung wurden feine Drahtstifte in Glassockel eingeschmolzen. Die Arbeit galt als Frauenarbeit, verlangte aber Konzentration, Materialwissen und ein genaues Gefühl für Temperatur und Tempo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p>„Von der Kollegin an der Presstellermaschine hängt es ab.“</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station iss-ausstellung-station\\u002d\\u002dfull\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station iss-ausstellung-station--full\"><!-- wp:image {\"id\":26368,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://192.168.2.31:8082/wp-content/uploads/2026/06/TFA-7329130-1.webp\" alt=\"\" class=\"wp-image-26368\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station__caption\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station__caption\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact iss-ausstellung-station__kicker\"} -->\n<p class=\"iss-kicker iss-kicker--compact iss-ausstellung-station__kicker\">Werkhalle</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Die Arbeit galt als Frauenarbeit.<br>Die Verantwortung ebenfalls.</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station iss-ausstellung-station\\u002d\\u002dsplit iss-ausstellung-station\\u002d\\u002dreverse\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station iss-ausstellung-station--split iss-ausstellung-station--reverse\"><!-- wp:image {\"id\":26370,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://192.168.2.31:8082/wp-content/uploads/2026/06/126896552_181100043650673_1483559125237673096_n-1024x796.webp\" alt=\"\" class=\"wp-image-26370\"/><figcaption class=\"wp-element-caption\">Quelle zur Qualifizierung im WF, 1960er Jahre</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station__copy\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station__copy\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact iss-ausstellung-station__kicker\"} -->\n<p class=\"iss-kicker iss-kicker--compact iss-ausstellung-station__kicker\">Qualifizierung</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Förderung und Belehrung</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Frauen sollten sich qualifizieren. Zugleich wurden ihre Lern- und Aufstiegsmöglichkeiten oft paternalistisch kommentiert. Die Quellen zeigen Förderung, aber auch Kontrolle und Erwartung.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station iss-ausstellung-station\\u002d\\u002dportrait\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station iss-ausstellung-station--portrait\"><!-- wp:image {\"id\":26372,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://192.168.2.31:8082/wp-content/uploads/2026/06/Bundesarchiv_Bild_183-70631-0001_Werk_fuer_Fernmeldewesen_Berlin_Brigadeleiterin-ausschnitt.webp\" alt=\"\" class=\"wp-image-26372\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station__caption\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station__caption\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact iss-ausstellung-station__kicker\"} -->\n<p class=\"iss-kicker iss-kicker--compact iss-ausstellung-station__kicker\">Biografie</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Anni Gent wird zur Aktivistin</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Anni Gent kam 1948 als ungelernte Arbeiterin in die Röhren-Sockelei. Verbesserungsvorschläge, Normerhöhung und Auszeichnungen machten sie früh zu einer öffentlichen Figur des Werks.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station iss-ausstellung-station\\u002d\\u002dfull iss-ausstellung-station\\u002d\\u002ddark\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station iss-ausstellung-station--full iss-ausstellung-station--dark\"><!-- wp:image {\"id\":26375,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://192.168.2.31:8082/wp-content/uploads/2026/06/Artikel-berliner-Zeitung-Ausschnitt-2.webp\" alt=\"\" class=\"wp-image-26375\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station__caption\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station__caption\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact iss-ausstellung-station__kicker\"} -->\n<p class=\"iss-kicker iss-kicker--compact iss-ausstellung-station__kicker\">Brigade</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Die „Gent-Mädels“ wurden zur Projektionsfläche.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Presse, Leistung, Erziehung und kollektive Arbeit griffen ineinander.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station iss-ausstellung-station\\u002d\\u002dsplit\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station iss-ausstellung-station--split\"><!-- wp:image {\"id\":26378,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://192.168.2.31:8082/wp-content/uploads/2026/06/36.webp\" alt=\"\" class=\"wp-image-26378\"/><figcaption class=\"wp-element-caption\">Feierstunde zum Internationalen Frauentag, WF, 1972</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-station__copy\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-station__copy\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact iss-ausstellung-station__kicker\"} -->\n<p class=\"iss-kicker iss-kicker--compact iss-ausstellung-station__kicker\">Anerkennung</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Anerkennung als Ritual</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Frauentag erschien als Feier und Würdigung. Zugleich zeigen die Quellen, welche Rollenbilder im Betrieb bestätigt und öffentlich inszeniert wurden.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-ausstellung-conclusion\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-ausstellung-conclusion\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact iss-ausstellung-station__kicker\"} -->\n<p class=\"iss-kicker iss-kicker--compact iss-ausstellung-station__kicker\">Fazit</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Die Geschichte der Frauen im WF ist keine Randgeschichte.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Werkhallen sind verschwunden oder haben ihre Funktion verändert. Geblieben sind Fotografien, Erinnerungen und Dokumente.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Aus ihnen entsteht kein vollständiges Bild. Aber genug, um die Frauen wieder sichtbar zu machen, die das Werk über Jahrzehnte mitgetragen haben.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:navigation {\"overlayMenu\":\"never\",\"className\":\"iss-ausstellung-research\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n<!-- wp:navigation-link {\"label\":\"Ort im Atlas\",\"url\":\"/schoneweide/\",\"kind\":\"custom\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"Archivbestand\",\"url\":\"/archiv/\",\"kind\":\"custom\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"Zeitzeugen\",\"url\":\"/archiv/?s=Zeitzeugen\",\"kind\":\"custom\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"Rundgänge\",\"url\":\"/fuehrungen/\",\"kind\":\"custom\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"Langfassung\",\"url\":\"/publikationen/\",\"kind\":\"custom\"} /-->\n<!-- /wp:navigation --></div>\n<!-- /wp:group -->', 'Frauen im Werk für Fernmeldewesen', 'Arbeit. Qualifizierung. Öffentlichkeit. Anerkennung.', 'publish', 'closed', 'closed', '', 'frauen-in-werk', '', '', '2026-06-10 10:46:35', '2026-06-10 08:46:35', '', '0', 'http://192.168.2.31:8082/?post_type=ausstellung&#038;p=26287', '0', 'ausstellung', '', '0'),
