('27', 'manual:22aecd19-4801-43c1-b050-d9903123d324', 'Frauen im Werk - Bildauswahl', 'Arbeits- und Quellenobjekte zur Ausstellung Frauen im Werk für Fernmeldewesen.', 'active', 'wp-post', '26287', 'http://192.168.2.31:8082/ausstellungen/frauen-in-werk/', '[]', '0', '0', '1', '2026-06-09 13:56:15', '2026-06-09 14:07:32')
